/** العلامات التجارية التي تتعامل بها الراعبي — لكل علامة صفحة خاصة على /brands/<slug>. */
export type Brand = { slug: string; brand: string; nameAr: string; logo: string; accent: string; website: string; about: string; founded?: string; hq?: string; tagline: string };
export const BRANDS: Brand[] = [
  { slug: "grasen", brand: "GRASEN", nameAr: "جراسين", logo: logoGrasen.url, accent: "#10a0b0", website: "https://grasen.com/", founded: "2010", hq: "لويانغ، الصين", tagline: "شواحن السيارات الكهربائية: شاحن AC حتى 22 kW، وشواحن DC سريعة حتى 420 kW، وشاحن 3 في 1، ووحدات شحن.", about: "تأسست GRASEN عام 2010 لتطوير وتصنيع معدات شحن المركبات الكهربائية وحلول التنمية المستدامة. تدير الشركة مجمعاً صناعياً في لويانغ ومراكز بحث وتطوير في لويانغ وبكين وشيآن. تشمل منتجاتها شواحن التيار المستمر السريعة والشواحن الجدارية للتيار المتردد مع برمجيات اتصال وإدارة للشحن." },
  { slug: "trina-solar", brand: "Trina Solar", nameAr: "ترينا سولار", logo: logoTrina.url, accent: "#0080d0", website: "https://www.trinasolar.com/", founded: "1997", hq: "تشانغتشو، الصين", tagline: "ألواح Vertex وVertex N من 595 إلى 720 واط، أحادية وثنائية الوجه.", about: "تأسست ترينا سولار عام 1997 وتعمل في المنتجات الكهروضوئية وتخزين الطاقة وحلول الأنظمة وخدمات الطاقة الرقمية. تشمل أعمالها البحث والتطوير وإنتاج وبيع الألواح الشمسية، إلى جانب حلول التتبع وتوليد الطاقة الموزعة." },
  { slug: "dyness", brand: "Dyness", nameAr: "داينس", logo: logoDyness.url, accent: "#00a0e0", website: "https://www.dyness.com", founded: "2017", hq: "سوتشو، الصين", tagline: "بطاريات منزلية وتجارية: Powerbox وPowerBrick وDL5.0 وStack100 وPowerRack وخزانة DH200F.", about: "تأسست داينس عام 2017 وتتخصص في البحث والتطوير والإنتاج وبيع أنظمة تخزين الطاقة. توزع منتجاتها في أكثر من 100 دولة ومنطقة، وأُنشئ مقرها العالمي في سوتشو عام 2023." },
  { slug: "luxpower", brand: "Luxpower", nameAr: "لاكس باور", logo: logoLuxpower.url, accent: "#4caf7d", website: "https://luxpowertek.com/", founded: "2017", hq: "شنتشن، الصين", tagline: "إنفرترات هجينة أحادية الطور: SNA وGEN-LB-EU وGEN2-LB-EU وLXP-LB-EU من 3 إلى 12 kW.", about: "تطوّر لوكس باور تك حلولاً ذكية لإدارة الطاقة وتخزينها للتطبيقات السكنية والتجارية في المناطق المتصلة بالشبكة وخارجها. تأسست الشركة عام 2017 مع التركيز على تطوير حلول تخزين الطاقة." },
  { slug: "sungrow", brand: "Sungrow", nameAr: "سنجرو", logo: logoSungrow.url, accent: "#f07000", website: "https://www.sungrowpower.com", founded: "1997", tagline: "إنفرترات مرتبطة بالشبكة من 25 إلى 150 kW وصندوق اتصال COM100E.", about: "تأسست صن جرو عام 1997 وتعمل في حلول الطاقة المتجددة. تشمل منتجاتها عواكس الطاقة الشمسية وأنظمة تخزين الطاقة وحلول شحن المركبات الكهربائية." },
  { slug: "atess", brand: "ATESS", nameAr: "أتيس", logo: logoAtess.url, accent: "#d01010", website: "https://www.atesspower.com", hq: "شنتشن، الصين", tagline: "إنفرترات هجينة HPS بقدرات 30 و50 و150 kW، وأنظمة تخزين PCS حتى 1500 kW، ومقوّمات RTF وجهاز المراقبة EnerLog.", about: "توفر ATESS حلول تخزين الطاقة الشمسية وشحن المركبات الكهربائية للأسواق العالمية. تهدف الشركة إلى إتاحة الطاقة النظيفة بأسعار مناسبة وتعزيز استقلال الأفراد والمجتمعات في الطاقة." },
];
export function findBrand(slug: string) {
  return BRANDS.find((b) => b.slug === slug);
}

const sheet = (url: string): ProductFile[] => [{ kind: "Datasheet", label: "الكتالوج / Datasheet الرسمي", url }];

