  "model": "HPS30000TL",
  "power": "30 kW",
  "description": "انفرتر هجين ثلاثي الطور متكامل بقدرة 30 كيلوواط للمنشآت التجارية الصغيرة، مع مفتاح تحويل تلقائي مدمج.",
  "about": "HPS30000TL من أتيس انفرتر هجين ثلاثي الطور بقدرة 30 كيلوواط وجهد 400 فولت، يجمع الألواح والبطارية والشبكة في جهاز واحد. يضم مفتاح تحويل تلقائي مدمجاً، وينتقل بين الشبكة والتشغيل المستقل خلال 10 مللي ثانية. يعمل مع بطاريات عالية الجهد من 260 إلى 700 فولت، ويقبل ألواحاً حتى 45 كيلوواط ذروة عبر ثلاثة متتبعات. يمكن توصيل حتى 10 وحدات على التوازي، والتحكم بالمولد عن بُعد.",
