  "about": "HPS150 من أتيس انفرتر هجين ثلاثي الطور بقدرة 150 كيلوواط وجهد 400 فولت، يجمع الألواح والبطارية والشبكة في خزانة واحدة بمحول مدمج. ينتقل بين الشبكة والتشغيل المستقل خلال 10 مللي ثانية، ويقبل ألواحاً حتى 225 كيلوواط ذروة. يعمل مع بطاريات عالية الجهد من 352 إلى 600 فولت، ويدعم التحكم بالمولد عن بُعد ومضاعفة القدرة بتوصيل وحدتين.",
