  "about": "سلسلة PCS1200HV/1500HV من أتيس نظام تحويل طاقة ثنائي الاتجاه لبطاريات الجهد العالي حتى 1500 فولت. يعمل منفرداً أو مع منظمات الشحن الشمسية وملحقات أخرى حسب نوع المشروع. يعتمد تقنية ثلاثية المستويات بكفاءة قصوى 98.5%، وتصميماً معيارياً يسهّل الصيانة. يدير شحن البطاريات وتفريغها، ويدعم التشغيل من الصفر (Black Start)، ودعم الشبكة بالقدرة الفعالة وغير الفعالة. يمكن توصيل حتى 8 وحدات على التوازي في التشغيل المستقل.",
