  "about": "EnerLog جهاز مراقبة من أتيس يجمع بيانات التشغيل من أجهزة المنظومة المختلفة عبر Modbus RS485، ويتصل بخادم أتيس عبر الإيثرنت. يدعم توصيل حتى 32 جهازاً، ويقبل حساسات خارجية لتفعيل خاصية منع التصدير إلى الشبكة. يحتوي على خادم ويب محلي لتسهيل الإعداد، ويُركّب على الجدار.",
